export default async function prepare({ messages, scheduledAt }, context) {
  if (!Array.isArray(messages) || messages.length > 1) throw Error("Invalid Gmail result");
  if (!messages.length) return { ready: false, messageId: "", prompt: "" };
  const m = messages[0];
  if (
    !m ||
    typeof m.messageId !== "string" ||
    !m.messageId ||
    typeof m.messageText !== "string" ||
    !m.messageText.trim() ||
    typeof m.sender !== "string" ||
    typeof m.subject !== "string"
  )
    throw Error("Invalid Gmail message");
  const seen = await context.state.get("seen-support-message-ids");
  if (seen !== null && (!Array.isArray(seen) || seen.some((x) => typeof x !== "string")))
    throw Error("Invalid saved message IDs");
  if (seen?.includes(m.messageId)) return { ready: false, messageId: "", prompt: "" };
  if (!Number.isFinite(Date.parse(scheduledAt))) throw Error("Invalid schedule time");
  return {
    ready: true,
    messageId: m.messageId,
    prompt: `Reported by ${m.sender || "unknown"}\nReported at: ${scheduledAt}\nSummary: ${m.subject || "(no subject)"}\nDescription:\n${m.messageText}`,
  };
}

