export default function fields({ result }) {
  const allowed = [
    "Technical",
    "Account",
    "Access",
    "Billing",
    "Product",
    "Training",
    "Feedback",
    "Complaints",
    "Security",
    "Privacy",
  ];
  if (
    !result ||
    typeof result.summary !== "string" ||
    !result.summary.trim() ||
    typeof result.description !== "string" ||
    !result.description.trim() ||
    !Array.isArray(result.labels) ||
    result.labels.length === 0 ||
    result.labels.some((x) => !allowed.includes(x)) ||
    !Number.isInteger(result.priority) ||
    result.priority < 1 ||
    result.priority > 5
  )
    throw Error("Invalid triage result");
  return {
    title: result.summary,
    description: result.description + "\n\n" + result.labels.map((x) => "#" + x).join(" "),
    priority: Math.min(result.priority, 4),
  };
}

