export default async function commit({ messageId, issueId }, context) {
  if (typeof messageId !== "string" || !messageId || typeof issueId !== "string" || !issueId)
    throw Error("Linear issue was not confirmed");
  const seen = await context.state.get("seen-support-message-ids");
  if (seen !== null && (!Array.isArray(seen) || seen.some((x) => typeof x !== "string")))
    throw Error("Invalid saved message IDs");
  if (!seen?.includes(messageId))
    await context.state.set("seen-support-message-ids", [...(seen ?? []), messageId]);
  return {};
}
